def solve(inputs: dict) -> float:
    n = int(inputs.get('n', inputs.get('people', inputs.get('count'))))
    k = int(inputs.get('k', inputs.get('step', inputs.get('every'))))
    survivor = 0
    for size in range(2, n + 1):
        survivor = (survivor + k) % size
    return float(survivor + 1)
